"use client";

import * as React from "react";
import { Menu, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";

interface ChatInterfaceProps {
  children?: React.ReactNode;
}

export default function ChatInterface({ children }: ChatInterfaceProps) {
  const [isMenuCollapsed, setIsMenuCollapsed] = React.useState(false);
  const [messages, setMessages] = React.useState<
    { text: string; sender: "ai" | "user" }[]
  >([{ text: "te muestro lo que quieres", sender: "ai" }]);
  const [input, setInput] = React.useState("");

  const menuItems = [
    { text: "revisar", onClick: () => {} },
    { text: "definir", onClick: () => {} },
    { text: "analizar", onClick: () => {} },
    { text: "organizame el dia", onClick: () => {} },
  ];

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim()) {
      setMessages([...messages, { text: input, sender: "user" }]);
      setInput("");
    }
  };

  return (
    <div className="flex h-screen bg-background">
      {/* Left Sidebar */}
      <div
        className={cn(
          "border-r p-4 flex flex-col gap-3 transition-all duration-300",
          isMenuCollapsed ? "w-20" : "w-64"
        )}
      >
        <div className="flex items-center gap-2 mb-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => setIsMenuCollapsed(!isMenuCollapsed)}
          >
            <Menu className="w-6 h-6" />
          </Button>
          {!isMenuCollapsed && (
            <span className="text-sm text-muted-foreground">menu</span>
          )}
        </div>
        {menuItems.map((item) => (
          <Button
            key={item.text}
            variant="outline"
            className={cn(
              "w-full justify-start normal-case text-base",
              isMenuCollapsed && "px-2"
            )}
            onClick={item.onClick}
          >
            {isMenuCollapsed ? item.text.charAt(0).toUpperCase() : item.text}
          </Button>
        ))}
      </div>

      {/* Middle Content Area */}
      <div className="flex-1 border-r p-4">{children}</div>

      {/* Chat Area */}
      <div className="w-[400px] flex flex-col">
        {/* Header */}
        <div className="border-b p-4">
          <div className="flex items-center gap-2">
            <div className="h-6 w-6 rounded-full bg-pink-200"></div>
            <span>yo</span>
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 p-4 overflow-auto">
          <div className="space-y-4">
            <Input
              value="quiero...."
              readOnly
              className="max-w-[200px] text-muted-foreground"
            />

            <div className="flex items-start gap-2">
              <div className="h-6 w-6 rounded-full bg-pink-200 flex-shrink-0"></div>
              <span className="font-medium mr-2">AI</span>
              <Card className="p-3 bg-muted">{messages[0].text}</Card>
            </div>
          </div>
        </div>

        {/* Input Area */}
        <form onSubmit={handleSend} className="border-t p-4 flex gap-2">
          <Input
            value={input}
            onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
              setInput(e.target.value)
            }
            placeholder="escribe lo que quieres"
            className="flex-1"
          />
          <Button type="submit" size="icon" variant="ghost">
            <Search className="h-4 w-4" />
          </Button>
        </form>
      </div>
    </div>
  );
}
